function ensureV1152KaimCards() {
  const problemGrid = document.querySelector("#bookProblemHubCard .book-choice-grid");
  if (problemGrid && !problemGrid.querySelector('[data-book-subject="K-AIM"]')) {
    const freeStudy = problemGrid.querySelector("#freeStudyBtn");
    const btn = document.createElement("button");
    btn.className = "book-choice-card";
    btn.type = "button";
    btn.dataset.bookSubject = "K-AIM";
    btn.innerHTML = '<img src="./assets/covers/kaim_cover.jpg" alt="K-AIM 표지"><strong>K-AIM</strong><span>세화 문제집 · 1,122문항</span>';
    problemGrid.insertBefore(btn, freeStudy || null);
  }
  const wrongGrid = document.querySelector("#wrongReviewHubCard .wrong-review-book-grid");
  if (wrongGrid && !wrongGrid.querySelector('[data-wrong-review-subject="K-AIM"]')) {
    const btn = document.createElement("button");
    btn.className = "book-choice-card";
    btn.type = "button";
    btn.dataset.wrongReviewSubject = "K-AIM";
    btn.innerHTML = '<img src="./assets/covers/kaim_cover.jpg" alt="K-AIM 표지"><strong>K-AIM</strong><span class="wrong-review-count">오답 기록 확인</span>';
    wrongGrid.appendChild(btn);
  }
  const theoryGrid = document.querySelector("#bookTheoryHubCard .theory-book-grid");
  if (theoryGrid && !theoryGrid.querySelector('[data-theory-subject="K-AIM"]')) {
    const btn = document.createElement("button");
    btn.id = "kaimTheoryBtn";
    btn.className = "book-choice-card theory-ready";
    btn.type = "button";
    btn.dataset.theorySubject = "K-AIM";
    btn.innerHTML = '<img src="./assets/covers/kaim_cover.jpg" alt="K-AIM 표지"><strong>K-AIM 학습 모드</strong><span>30단계 · 검수 완료 1,038문항 연계</span>';
    const comingSoon = theoryGrid.querySelector(".theory-coming-soon");
    theoryGrid.insertBefore(btn, comingSoon || null);
  }
}
ensureV1152KaimCards();

